// RunSSLCert checks the SSL certificate details for the target:port
func RunSSLCert(image, target, port string) DiagResult {
	connect := fmt.Sprintf("%s:%s", target, port)
	shellCmd := fmt.Sprintf(
		`echo | openssl s_client -showcerts -servername %s -connect %s 2>/dev/null | openssl x509 -inform pem -noout -text | grep "Issuer\|Subject\|Not After"`,
		target, connect,
	)
	return runDiagHost(image, []string{"/bin/sh", "-c", shellCmd})
}

